import { words, phrases, translate, dailyWord, shuffled } from './lingo.js';

const $ = (s, scope=document) => scope.querySelector(s);
const $$ = (s, scope=document) => [...scope.querySelectorAll(s)];
const escape = text => String(text).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const paths = {
  translate:'M4 5h12M10 3v2m4 0c-1 6-5 9-10 11m2-8c2 4 5 6 9 8m0 4 4-11 4 11m-7-3h6',
  book:'M3 4h6a4 4 0 0 1 3 1 4 4 0 0 1 3-1h6v16h-6a4 4 0 0 0-3 1 4 4 0 0 0-3-1H3zm9 1v16',
  game:'M8 7h8c4 0 5 3 6 10 0 3-3 4-5 1l-2-2H9l-2 2c-2 3-5 2-5-1C3 10 4 7 8 7zm-2 4v4m-2-2h4m8-1h.01m3 2h.01',
  heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8z',
  arrow:'M5 12h14m-5-5 5 5-5 5',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',copy:'M9 8h11v13H9zM5 16H3V3h11v2',sound:'m11 4-6 5H2v6h3l6 5zm4 4a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',search:'M21 21l-6-6m2-6a7 7 0 1 1-14 0 7 7 0 0 1 14 0',close:'m6 6 12 12M6 18 18 6',refresh:'M20 7v5h-5M4 17v-5h5m10-5a8 8 0 0 0-14-2M5 17a8 8 0 0 0 14 2',chevron:'m9 5 7 7-7 7',phone:'M7 2h10v20H7zM10 18h4',trophy:'M7 3h10v7a5 5 0 0 1-10 0zm0 2H3v4a4 4 0 0 0 4 4m10-8h4v4a4 4 0 0 1-4 4m-5 2v5m-5 1h10',check:'m5 12 4 4L19 6',bolt:'m13 2-9 12h7l-1 8 10-12h-7z',shuffle:'m3 5 4 0 10 14h4m-4-4 4 4-4 3M3 19h4l3-4m4-7 3-3h4m-4-3 4 3-4 4'
};
const icon = (name, cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
function paintIcons(){$$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function readStore(key,fallback) { try { return JSON.parse(localStorage.getItem(key)) ?? fallback; } catch { return fallback; } }
function persist() { try { localStorage.setItem('gaylingua-saved',JSON.stringify(saved)); localStorage.setItem('gaylingua-stats',JSON.stringify(stats)); } catch { toast('Storage is unavailable. Your progress will last for this visit.'); } updateCounts(); }
let saved = readStore('gaylingua-saved',[]); if(!Array.isArray(saved)) saved=[];
let stats=readStore('gaylingua-stats',{xp:0,rounds:0,best:0}); if(!stats || typeof stats!=='object') stats={xp:0,rounds:0,best:0};
let sourceText='',sourceLanguage='auto',result=null,activeCategory='All words',searchText='',collectionTab='all';
let game=null,gameTimer=null,toastTimer=null,installPrompt=null;
const main=$('#main');
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function updateCounts(){$('#saved-count').textContent=saved.length;}
const isSaved = id=>saved.some(item=>item.id===id);
function saveWord(id){const w=words.find(w=>w.id===id);if(!w)return;toggleSaved({id:w.id,type:'word',title:w.word,subtitle:w.meaning});}
function toggleSaved(item){if(isSaved(item.id)){saved=saved.filter(x=>x.id!==item.id);toast('Removed from your collection');}else{saved.push(item);toast('Saved to your collection, beshie!');}persist();$$(`[data-save="${CSS.escape(item.id)}"]`).forEach(btn=>{btn.classList.toggle('saved',isSaved(item.id));btn.setAttribute('aria-pressed',String(isSaved(item.id)));btn.setAttribute('aria-label',isSaved(item.id)?'Unsave '+item.title:'Save '+item.title);});}
function wordCard(w){return `<article class="word-card"><div class="word-card-top"><span class="word-emoji">${w.emoji}</span><button class="icon-button save-word ${isSaved(w.id)?'saved':''}" data-save="${w.id}" aria-label="${isSaved(w.id)?'Unsave':'Save'} ${w.word}" aria-pressed="${isSaved(w.id)}">${icon('heart')}</button></div><span class="category-label">${w.category}</span><button class="word-title" data-detail="${w.id}">${w.word} ${icon('arrow')}</button><p>${w.meaning}</p><div class="word-example">“${escape(w.example)}”</div></article>`;}
function heading(kicker,title,description,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div>${extra}</div>`;}
function gameCards(){return `<div class="game-grid"><button class="game-card quiz-card" data-game="quiz"><div><span class="game-type">THE QUICK THINKER</span><h3>Guess the lingo</h3><p>Know your charot from your chika?<br>Put your beki vocabulary to the test.</p><span class="game-meta">5 questions <span>·</span> +10 XP per correct answer</span></div><div class="game-art quiz-art" aria-hidden="true"><span class="question-back">?</span><span class="question-front">?</span><span class="art-star">✦</span></div><span class="game-arrow">${icon('arrow')}</span></button><button class="game-card match-card" data-game="match"><div><span class="game-type">THE PERFECT PAIR</span><h3>Match, beshie!</h3><p>A little mix. A little match.<br>Connect the words to their meanings.</p><span class="game-meta">4 pairs <span>·</span> +40 XP per round</span></div><div class="game-art match-art" aria-hidden="true"><span>BE</span><span>SHIE</span><i>♡</i></div><span class="game-arrow">${icon('arrow')}</span></button></div>`;}
function translatorPage(){const day=dailyWord();return `<section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="small-line"></span> SAME MEANING. MORE PERSONALITY.</div><h1>Your words.<br>A little <span class="extra-word">extra.<svg viewBox="0 0 230 16" aria-hidden="true"><path d="M4 11C51 0 149 0 224 8M21 15C85 6 157 6 202 13"/></svg></span><span class="hero-spark">✳</span></h1><p>From everyday talk to full-on <em>bongga.</em><br>Translate Filipino & English into the art of Swardspeak.</p><div class="hero-stickers"><span class="sticker lime-sticker">100% you</span><span class="sticker pink-sticker">a little more ✨</span><span class="handwritten">Go on, express yourself. ↗</span></div></div><article class="daily-card"><div class="daily-card-top"><span>YOUR DAILY LINGO</span><span>✧</span></div><div class="daily-word">${day.word}<span>✳</span></div><span class="daily-pronunciation">${day.category.toLowerCase()} · swardspeak</span><p>${day.meaning}</p><div class="daily-example">“${escape(day.example)}”</div><button class="daily-link" data-detail="${day.id}">Meet your new favorite word ${icon('arrow')}</button><div class="daily-decoration" aria-hidden="true">✳</div></article></section>
<section class="translator-section" aria-label="Translator"><div class="section-title"><h2>Let’s talk, beshie. <span>↘</span></h2><span class="section-caption">A LITTLE SWITCH. A WHOLE NEW VIBE.</span></div><div class="translator-card"><div class="translation-languages"><div class="source-select"><label class="sr-only" for="source-language">Source language</label><select id="source-language"><option value="auto" ${sourceLanguage==='auto'?'selected':''}>Filipino / English</option><option value="filipino" ${sourceLanguage==='filipino'?'selected':''}>Filipino</option><option value="english" ${sourceLanguage==='english'?'selected':''}>English</option></select><span class="language-tag">FROM</span></div><span class="direction-icon">${icon('arrow')}</span><div class="target-language"><span class="target-dot"></span>Swardspeak<span class="language-tag">TO FABULOUS</span></div></div><div class="translation-panes"><div class="input-pane"><label class="sr-only" for="source-text">Text to translate</label><textarea id="source-text" maxlength="500" placeholder="What’s on your mind, beshie?" spellcheck="false">${escape(sourceText)}</textarea><div class="input-bottom"><span id="character-count">${sourceText.length}<span> / 500</span></span><button class="icon-button" id="clear-input" aria-label="Clear input">${icon('close')}</button></div></div><div class="output-pane"><div id="translation-result" aria-live="polite">${resultHTML()}</div><div class="output-bottom"><span class="output-label">${icon('spark')} A little flair goes a long way</span><div class="output-actions"><button class="icon-button" id="speak-result" aria-label="Read translation aloud" ${!result?.text?'disabled':''}>${icon('sound')}</button><button class="icon-button" id="copy-result" aria-label="Copy translation" ${!result?.text?'disabled':''}>${icon('copy')}</button><button class="icon-button" id="save-result" aria-label="Save translation" ${!result?.matches.length?'disabled':''}>${icon('heart')}</button></div></div></div></div><div class="translator-bottom"><div class="try-examples"><span>Try a little:</span><button data-example="You are beautiful">Ang ganda mo ✨</button><button data-example="Let's eat">Let’s eat 🍜</button><button data-example="I am tired">Pagod na ako 🫠</button></div><button id="translate-button" class="primary-button">Translate ${icon('spark')}</button></div></div><div id="translation-explanation">${explanationHTML()}</div><p class="translator-note"><span>ⓘ</span> Beki lingo is creative & ever-changing. This is a phrase-based learning tool. Context is queen.</p></section>
<section class="play-preview"><div class="section-title"><h2>Less scroll. More <span class="pink-text">slay.</span></h2><a class="text-link" href="#play">Play & learn ${icon('arrow')}</a></div>${gameCards()}</section><div class="community-strip"><span class="community-mark">✳</span><p><b>More than words. A way to belong.</b><span>Rooted in Filipino LGBTQ+ creativity. Open to every curious soul.</span></p><span class="community-hearts">♡ ♡ ♡</span></div>`;}
function resultHTML(){if(!result)return `<div class="empty-result"><span class="empty-spark">✳</span><p>A little magic goes here.</p><span>Your Swardspeak translation is one click away.</span></div>`;return `<span class="result-tag">${result.kind==='phrase'?'PHRASE TRANSLATION':result.kind==='words'?'WORD SUBSTITUTIONS':'NO MATCH YET'}</span><p class="translated-text">${escape(result.text)}</p>${result.kind==='unmatched'?'<p class="no-match">We don’t have a lingo match for this yet. Try a shorter phrase or explore the library.</p>':''}`;}
function explanationHTML(){if(!result?.matches.length)return '';return `<div class="translation-breakdown"><span>THE LINGO LOWDOWN</span>${result.matches.map(w=>`<button data-detail="${w.id}"><b>${w.word}</b> <span>${w.meaning}</span>${icon('arrow')}</button>`).join('')}</div>${result.kind==='words'?'<p class="substitution-note">Matched words have been swapped; the rest stays as written. This may not read like natural Swardspeak.</p>':''}`;}
function runTranslation(){sourceText=$('#source-text').value.trim();sourceLanguage=$('#source-language').value;if(!sourceText){toast('Give us a little something to translate.');$('#source-text').focus();return;}result=translate(sourceText,sourceLanguage);$('#translation-result').innerHTML=resultHTML();$('#translation-explanation').innerHTML=explanationHTML();['speak-result','copy-result'].forEach(id=>$('#'+id).disabled=!result.text);$('#save-result').disabled=!result.matches.length;$('#save-result').classList.toggle('saved',isSaved('phrase-'+sourceText.toLowerCase()));}
function dictionaryPage(){return `${heading('THE LINGO LIBRARY','Big words. <span class="pink-text">Bigger personality.</span>','A little chika on what it means, how to say it, and when to use it.')}<div class="library-toolbar"><div class="search-field">${icon('search')}<label class="sr-only" for="dictionary-search">Search words or meanings</label><input id="dictionary-search" type="search" placeholder="Find a word, a meaning, a vibe…" value="${escape(searchText)}"></div><span>${words.length} words. Endless expression.</span></div><div class="filter-chips" role="group" aria-label="Word categories">${['All words','Everyday','Expressions','Feelings','People'].map(cat=>`<button class="filter-chip ${cat===activeCategory?'active':''}" data-category="${cat}" aria-pressed="${cat===activeCategory}">${cat}</button>`).join('')}</div><div id="dictionary-grid" class="word-grid">${filteredWords()}</div><div class="library-note"><span>✳</span><p><b>Language lives in its people.</b> These are starter meanings, not fixed rules. Usage varies across communities, generations, and conversations. Respect the people behind the words.</p><button class="text-link" id="sources-button">Our reading list ↗</button></div>`;}
function filteredWords(){const filtered=words.filter(w=>(activeCategory==='All words'||w.category===activeCategory)&&[w.word,w.meaning,w.filipino,...w.aliases].some(s=>s.toLowerCase().includes(searchText.toLowerCase())));return filtered.length?filtered.map(wordCard).join(''):`<div class="empty-state"><span>⌕</span><h3>No words found, beshie.</h3><p>Try another spelling or a different category.</p><button class="secondary-button" id="reset-search">Show all words</button></div>`;}
function playPage(){return `${heading('A LITTLE PLAY GOES A LONG WAY','Play it. <span class="pink-text">Say it. Slay it.</span>','Build your beki vocabulary, one little win at a time.',`<div class="xp-badge">${icon('bolt')}<b>${stats.xp} XP</b><span>and counting</span></div>`)}${game?gameHTML():`<div class="play-banner"><div><span class="eyebrow">YOUR NEXT LEVEL? A LITTLE MORE YOU.</span><h2>Learning looks good on you.</h2><p>No pressure. No timer. Just a little friendly wordplay.</p></div><span aria-hidden="true">✳</span></div>${gameCards()}<div class="stats-row"><div>${icon('trophy')}<b>${stats.rounds}</b><span>rounds completed</span></div><div>${icon('bolt')}<b>${stats.xp}</b><span>total XP earned</span></div><div>${icon('spark')}<b>${stats.best}/5</b><span>best quiz score</span></div></div><div class="play-tip">${icon('book')}<p>A little warm-up? <a href="#dictionary">Explore the lingo library</a> before you play.</p></div>`}`;}
function savedPage(){const items=saved.filter(x=>collectionTab==='all'||x.type===collectionTab);return `${heading('YOUR PERSONAL LITTLE WORD BANK','Your collection. <span class="pink-text">Very you.</span>','Keep your favorite expressions and translations close. Saved on this device.')}<div class="filter-chips">${[['all','Everything'],['word','Words'],['phrase','Translations']].map(([val,label])=>`<button class="filter-chip ${collectionTab===val?'active':''}" data-collection="${val}" aria-pressed="${collectionTab===val}">${label}</button>`).join('')}</div><div class="word-grid">${items.length?items.map(item=>{if(item.type==='word'){const word=words.find(w=>w.id===item.id);return word?wordCard(word):'';}return `<article class="word-card saved-phrase"><div class="word-card-top"><span class="word-emoji">💌</span><button class="icon-button saved" data-remove="${escape(item.id)}" aria-label="Remove saved translation">${icon('heart')}</button></div><span class="category-label">TRANSLATION</span><h3>${escape(item.title)}</h3><p>${escape(item.subtitle)}</p><button class="text-link" data-use="${escape(item.title)}">Translate again ${icon('arrow')}</button></article>`;}).join(''):`<div class="empty-state"><span>♡</span><h3>A little empty. A lot of possibility.</h3><p>Tap the heart on a word or translation to make it yours.</p><a href="#dictionary" class="primary-button">Find your favorites ${icon('arrow')}</a></div>`}</div>`;}
function currentPage(){const page=location.hash.slice(1);return ['translate','dictionary','play','saved'].includes(page)?page:'translate';}
function render(){const page=currentPage();if(page!=='play'){clearTimeout(gameTimer);game=null;}main.innerHTML=page==='translate'?translatorPage():page==='dictionary'?dictionaryPage():page==='play'?playPage():savedPage();$$('[data-page]').forEach(el=>{el.classList.toggle('active',el.dataset.page===page);if(el.dataset.page===page)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});$('#breadcrumb-label').textContent=({translate:'extra',dictionary:'discovery',play:'wordplay',saved:'favorites'})[page];paintIcons();}
function modal(html){$('#dialog-content').innerHTML=html;$('#info-dialog').showModal();}
function detail(id){const w=words.find(w=>w.id===id);if(!w)return;modal(`<span class="detail-emoji">${w.emoji}</span><div class="eyebrow">${w.category} · SWARDSPEAK</div><h2>${w.word}</h2><p class="detail-meaning">${w.meaning}</p><p class="detail-filipino">Filipino: ${w.filipino}</p><blockquote>“${escape(w.example)}”</blockquote><p>${w.note}</p><button class="primary-button ${isSaved(id)?'saved':''}" data-save="${id}" aria-pressed="${isSaved(id)}">${icon('heart')} ${isSaved(id)?'Saved to collection':'Save this word'}</button>`);}
function startGame(type){clearTimeout(gameTimer);if(type==='quiz'){game={type,questions:shuffled(words).slice(0,5).map(w=>({word:w,options:shuffled([w,...shuffled(words.filter(x=>x.id!==w.id)).slice(0,3)])})),index:0,correct:0,answered:null,done:false};}else{const selected=shuffled(words).slice(0,4);game={type,words:selected,left:shuffled(selected),right:shuffled(selected),selected:null,matched:[],wrong:[],attempts:0,done:false};}if(currentPage()!=='play')location.hash='play';else render();}
function gameHTML(){return `<section class="game-panel"><div class="game-panel-top"><button id="exit-game" class="text-link">← All games</button><span>${game.type==='quiz'?'GUESS THE LINGO':'MATCH, BESHIE!'}</span><span>${icon('bolt')} ${stats.xp} XP</span></div>${game.done?gameComplete():game.type==='quiz'?quizHTML():matchHTML()}</section>`;}
function quizHTML(){const q=game.questions[game.index];return `<div class="quiz-progress"><span>Question ${game.index+1} of 5</span><span>${game.correct} correct</span></div><div class="progress-track"><span style="width:${game.index/5*100}%"></span></div><div class="quiz-question"><span>${q.word.emoji}</span><p>What does this word mean?</p><h2>${q.word.word}</h2></div><div class="quiz-options">${q.options.map((w,i)=>`<button data-answer="${w.id}" ${game.answered?'disabled':''} class="${game.answered?(w.id===q.word.id?'correct':w.id===game.answered?'incorrect':''):''}"><span>${String.fromCharCode(65+i)}</span>${w.meaning}${game.answered&&w.id===q.word.id?icon('check'):''}</button>`).join('')}</div>${game.answered?`<div class="answer-feedback ${game.answered===q.word.id?'right':'wrong'}"><b>${game.answered===q.word.id?'Pakak! You got it. +10 XP':'A little learning moment.'}</b><p>${escape(q.word.example)}</p><button class="primary-button" id="next-question">${game.index===4?'See my results':'Next question'} ${icon('arrow')}</button></div>`:'<p class="game-hint">Take your time, beshie. You’ve got this.</p>'}`;}
function matchHTML(){return `<div class="match-heading"><span>THE PERFECT PAIR</span><h2>A match made in <em>beki.</em></h2><p>Tap a word, then tap its meaning. Find all four pairs.</p></div><div class="match-status"><span>${game.matched.length} / 4 pairs found</span><span>${game.attempts} attempts</span></div><div class="match-board"><div>${game.left.map(w=>`<button class="match-tile ${game.selected===w.id?'selected':''} ${game.matched.includes(w.id)?'matched':''}" data-match-word="${w.id}" ${game.matched.includes(w.id)?'disabled':''}>${w.emoji} ${w.word}${game.matched.includes(w.id)?icon('check'):''}</button>`).join('')}</div><div>${game.right.map(w=>`<button class="match-tile meaning ${game.matched.includes(w.id)?'matched':''} ${game.wrong.includes(w.id)?'incorrect':''}" data-match-meaning="${w.id}" ${game.matched.includes(w.id)?'disabled':''}>${w.meaning}${game.matched.includes(w.id)?icon('check'):''}</button>`).join('')}</div></div><p class="game-hint" role="status">${game.wrong.length?'Not quite. Try another meaning, beshie.':game.selected?'Now choose its meaning on the right.':'Pick any word on the left to start.'}</p>`;}
function gameComplete(){const quiz=game.type==='quiz';return `<div class="game-complete"><span class="complete-emoji">${quiz&&game.correct<3?'🌱':'🏆'}</span><div class="eyebrow">A LITTLE WIN. A BIG VIBE.</div><h2>${quiz&&game.correct<3?'Growing, beshie!':'Bongga, beshie!'}</h2><p>${quiz?`You got <b>${game.correct} out of 5</b> words right.`:`All four pairs found in <b>${game.attempts} attempts.</b>`}</p><div class="earned-xp">${icon('bolt')} +${quiz?game.correct*10:40} XP earned</div><p class="completion-note">Your progress is saved on this device.</p><div class="completion-actions"><button class="primary-button" data-game="${game.type}">Play again ${icon('refresh')}</button><button class="secondary-button" id="exit-game">Explore games</button></div><a class="text-link" href="#dictionary">Brush up in the lingo library ↗</a></div>`;}
function finishGame(){if(game.done)return;game.done=true;stats.rounds++;if(game.type==='match')stats.xp+=40;else stats.best=Math.max(stats.best,game.correct);persist();render();}

document.addEventListener('click',async event=>{
  const el=event.target.closest('button,a');if(!el)return;
  if(el.dataset.detail){detail(el.dataset.detail);return;}
  if(el.dataset.save){saveWord(el.dataset.save);if($('#info-dialog').open)detailRefresh(el.dataset.save);return;}
  if(el.dataset.remove){saved=saved.filter(x=>x.id!==el.dataset.remove);persist();render();toast('Translation removed');return;}
  if(el.dataset.example){$('#source-text').value=el.dataset.example==='You are beautiful'?'Ang ganda mo':el.dataset.example==='I am tired'?'Pagod na ako':el.dataset.example;sourceText=$('#source-text').value;$('#character-count').innerHTML=sourceText.length+'<span> / 500</span>';runTranslation();return;}
  if(el.dataset.game){if($('#info-dialog').open)$('#info-dialog').close();startGame(el.dataset.game);return;}
  if(el.dataset.category){activeCategory=el.dataset.category;render();return;}
  if(el.dataset.collection){collectionTab=el.dataset.collection;render();return;}
  if(el.dataset.use){sourceText=el.dataset.use;result=translate(sourceText,sourceLanguage);location.hash='translate';return;}
  if(el.dataset.answer&&game?.type==='quiz'&&!game.answered){const answer=el.dataset.answer;game.answered=answer;if(answer===game.questions[game.index].word.id){game.correct++;stats.xp+=10;persist();}render();return;}
  if(el.dataset.matchWord&&game?.type==='match'&&!game.done){game.selected=el.dataset.matchWord;game.wrong=[];render();return;}
  if(el.dataset.matchMeaning&&game?.type==='match'&&!game.done){if(!game.selected){toast('Pick a word on the left first.');return;}game.attempts++;if(game.selected===el.dataset.matchMeaning){game.matched.push(game.selected);game.selected=null;game.wrong=[];if(game.matched.length===4){finishGame();return;}}else game.wrong=[el.dataset.matchMeaning];render();return;}
  switch(el.id){
    case 'translate-button':runTranslation();break;
    case 'clear-input':sourceText='';result=null;render();$('#source-text').focus();break;
    case 'copy-result':if(result?.text){try{await navigator.clipboard.writeText(result.text);toast('Copied. Go spread the chika!');}catch{toast('Copy unavailable. Select the translation to copy it.');}}break;
    case 'speak-result':if(!('speechSynthesis' in window)){toast('Read aloud isn’t supported in this browser.');break;}if(result?.text){speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(result.text);utterance.lang='fil-PH';utterance.rate=.85;utterance.onerror=()=>toast('Read aloud is unavailable on this device.');speechSynthesis.speak(utterance);}break;
    case 'save-result':if(result?.matches.length)toggleSaved({id:'phrase-'+sourceText.toLowerCase(),type:'phrase',title:sourceText,subtitle:result.text});break;
    case 'reset-search':activeCategory='All words';searchText='';render();break;
    case 'next-question':if(!game?.answered)return;if(game.index===4)finishGame();else{game.index++;game.answered=null;render();}break;
    case 'exit-game':game=null;clearTimeout(gameTimer);render();break;
    case 'about-button':modal(`<div class="eyebrow">HELLO, BESHIE.</div><h2>A little language.<br>A lot of belonging.</h2><p>Gaylingua is a playful introduction to Swardspeak: creative Filipino queer expression, with roots in LGBTQ+ communities.</p><p>Translate curated Filipino and English phrases, explore ${words.length} starter words, and learn through games. Usage evolves and varies by community; listen to speakers and use the language with care.</p><p>Translation, favorites, and games run on your device. Your saved collection and progress stay in this browser.</p><button class="secondary-button" id="sources-button">Explore the reading list ↗</button>`);break;
    case 'sources-button':modal(`<div class="eyebrow">ROOTED IN REAL LANGUAGE</div><h2>Keep the chika going.</h2><p>These readings provide context for Swardspeak’s creativity and changing usage. Our short definitions and sample sentences are learning aids, not a complete dictionary.</p><ul class="source-list"><li><a href="https://www.researchgate.net/publication/369080094_Swardspeak_as_a_Communication_Medium_Among_University_Students_Empirical_Evidence_from_the_Philippines" target="_blank" rel="noopener noreferrer">Swardspeak as a Communication Medium Among University Students (2023) ↗</a></li><li><a href="https://sukisok.com/index.php/sjas/article/view/43" target="_blank" rel="noopener noreferrer">“Charot!” in Everyday Filipino Talk ↗</a></li></ul><p>Many expressions are now shared with wider Filipino slang. Context matters more than a fixed label.</p>`);break;
    case 'profile-button':modal(`<div class="eyebrow">YOUR LITTLE WINS</div><h2>Hey, beshie. ✳</h2><p>You’ve earned <b>${stats.xp} XP</b>, completed <b>${stats.rounds} rounds</b>, and collected <b>${saved.length} favorites</b>.</p><p>Best quiz: <b>${stats.best}/5</b>. Progress is stored on this device.</p><button class="primary-button" data-game="quiz" id="profile-play">Keep learning ${icon('arrow')}</button>`);break;
    case 'install-button':if(installPrompt){await installPrompt.prompt();installPrompt=null;$('#install-button').hidden=true;}break;
  }
  if(el.dataset.game&&$('#info-dialog').open)$('#info-dialog').close();
});
function detailRefresh(id){const w=words.find(w=>w.id===id);const btn=$('#dialog-content [data-save]');if(btn)btn.innerHTML=icon('heart')+' '+(isSaved(id)?'Saved to collection':'Save this word');}
document.addEventListener('input',event=>{if(event.target.id==='source-text'){sourceText=event.target.value;$('#character-count').innerHTML=sourceText.length+'<span> / 500</span>';if(result){result=null;$('#translation-result').innerHTML=resultHTML();$('#translation-explanation').innerHTML='';['copy-result','save-result','speak-result'].forEach(id=>$('#'+id).disabled=true);}}if(event.target.id==='dictionary-search'){searchText=event.target.value;$('#dictionary-grid').innerHTML=filteredWords();}});
document.addEventListener('change',event=>{if(event.target.id==='source-language')sourceLanguage=event.target.value;});
document.addEventListener('keydown',event=>{if(event.target.id==='source-text'&&(event.ctrlKey||event.metaKey)&&event.key==='Enter'){event.preventDefault();runTranslation();}});
$('.dialog-close').addEventListener('click',()=>$('#info-dialog').close());
$('#info-dialog').addEventListener('click',event=>{if(event.target===$('#info-dialog')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.target.close();}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;$('#install-button').hidden=false;});
window.addEventListener('appinstalled',()=>{installPrompt=null;$('#install-button').hidden=true;toast('Installed. Welcome home, beshie!');});
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
updateCounts();render();
